@patch
def encode(self: Geology) -> str:
    """Encode Geology to string format."""
    lines = []
    lines.append(f"name:{self.name}")
    
    # Encode plates
    lines.append(f"+plates:{len(self.plates)}")
    for plate in self.plates:
        lines.append(plate.encode())
    lines.append("-plates")
    
    # Encode terrain
    lines.append("+terrain")
    lines.append(self.terrain.encode())
    lines.append("-terrain")
    
    # Encode basins (expensive to compute)
    lines.append("+basins")
    lines.append(self.basins.encode())
    lines.append("-basins")
    
    return '\n'.join(lines)

